function geom = cw4_wingGeometry(mTO, WS, LEMAC, p)
% Wing geometry generated by the design point.

W = mTO*p.g;
S = W/WS;
b = sqrt(p.wing.AR*S);
cr = 2*S/(b*(1+p.wing.taper));
ct = p.wing.taper*cr;
MAC = (2/3)*cr*((1+p.wing.taper+p.wing.taper^2)/(1+p.wing.taper));
yMAC = (b/6)*((1+2*p.wing.taper)/(1+p.wing.taper));
wingAC = LEMAC + 0.25*MAC;

geom.S = S;
geom.b = b;
geom.cr = cr;
geom.ct = ct;
geom.MAC = MAC;
geom.yMAC = yMAC;
geom.LEMAC = LEMAC;
geom.wingAC = wingAC;
geom.AR = p.wing.AR;
geom.taper = p.wing.taper;
geom.spanFuselageRatio = b/p.fuselage.length_m;

end
